            /// <summary>Advances to the next record.</summary>
            /// <returns><see langword="false"/> when the source ends exactly after the last record.</returns>
            public bool MoveNext()
            {
                int next = this.index < 0 ? 0 : this.offset + 16;
                if (next >= this.source.Length)
                {
                    return false;
                }
                if (this.source.Length - next < 16)
                {
                    throw global::CStructSharp.Generated.RecordSequence.Partial(this.source.Length - next, 16, "root", this.index + 1, next);
                }
                this.offset = next;
                this.index++;
                return true;
            }
        }
    }
}
